head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst73200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst73200.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_1_onclick
 * @description tab_1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.tab_1_onclick = function(e){
    try {
        scwin.tabMenu('1');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst73200.tab_1_onclick' }); }
};

/**
 * @method
 * @name tab_2_onclick
 * @description tab_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.tab_2_onclick = function(e){
    try {
        scwin.tabMenu('2');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst73200.tab_2_onclick' }); }
};

/**
 * @method
 * @name tab_3_onclick
 * @description tab_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.tab_3_onclick = function(e){
    try {
        scwin.tabMenu('3');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst73200.tab_3_onclick' }); }
};

/**
 * @method
 * @name tab_4_onclick
 * @description tab_4 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.tab_4_onclick = function(e){
    try {
        scwin.tabMenu('4');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst73200.tab_4_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tabMenu
 * @description tab Menu 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.tabMenu = function (index) {
    for (let i = 1; i <= 4; i++) {
        const achObj = $c.util.getComponent("tab_" + i);
        if (index === i) {
            achObj.className = "on";
        } else {
            achObj.className = "";
        }
    }
    let url = "";
    if (index === 1) {
        url = "/listinvstg/puboframt.do?method=searchPubofrAmtMain";
    } else {
        if (index === 2) {
            url = "/listinvstg/industrypubofrstat.do?method=searchIndustryPubofrStatMain";
        } else {
            if (index === 3) {
                url = "/listinvstg/pubofrscale.do?method=searchPubofrScaleMain";
            } else {
                if (index === 4) {
                    url = "/listinvstg/spacpubofrstat.do?method=searchSpacPubofrStatMain";
                }
            }
        }
    }
    $c.util.getComponent("iframeList1").src = url;
};
